import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CRPOboOd.js";var i=JSON.parse(`{"title":"Conventions","description":"","frontmatter":{"title":"Conventions","order":1},"headers":[],"relativePath":"conventions/index.md","filePath":"conventions/index.md"}`),a={name:`conventions/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1793506373000`},[...i[0]||=[e(`<h1 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to “Conventions”">​</a></h1><p>Go services follow DDD with CQRS. The full rules are in <a href="https://github.com/notopia-uit/notopia/blob/main/docs/ai/GO_CLEAN_ARCH.md" target="_blank" rel="noreferrer"><code>docs/ai/GO_CLEAN_ARCH.md</code></a>; this page is a summary. The Note service (<code>internal/note</code>) is the reference implementation.</p><ul><li><strong>Layers</strong>: <code>controller -&gt; app -&gt; domain &lt;- infra</code>. <code>domain</code> is stdlib only, <code>controller</code> imports <code>app</code> only (never <code>domain</code>), wiring with google/wire is the only place that joins layers.</li><li><strong>CQRS</strong>: commands (<code>cmd_*.go</code>) return only an error and go through <code>UnitOfWork</code>, aggregate and repo; queries (<code>q_*.go</code>) return app models only and use a read-model port that bypasses aggregates. Write and read SQL are separate files.</li><li><strong>Models</strong>: domain models have unexported fields with <code>NewX</code> / <code>UnmarshalX</code>; app models never embed domain types. Enums are <code>uint8</code> iota types with explicit mappers at every boundary.</li><li><strong>sqlc</strong>: named args only, dynamic filters with <code>-- :if @param</code>.</li><li><strong>Events</strong>: topics are constants in <code>component/eventtopic.go</code>, payloads come from <code>api/share</code>, integration events go through the transactional outbox.</li><li><strong>Contracts</strong>: change <code>api/</code> or <code>proto/</code> first, then <code>nx gen api</code> / <code>nx gen proto</code>.</li></ul>`,3)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};